// Production-grade Distributed Lock Handler in Node.js / TypeScript
import Redis from 'ioredis';
import { randomUUID } from 'crypto';

const redis = new Redis(process.env.REDIS_URL);

// Atomic Lua Script: Only delete the lock if the value matches the caller's unique token
const RELEASE_LOCK_LUA = `
  if redis.call("get", KEYS[1]) == ARGV[1] then
    return redis.call("del", KEYS[1])
  else
    return 0
  end
`;

export async function holdSeat(seatId: string, timeoutSeconds = 480) {
  const lockToken = randomUUID(); // Cryptographic lease token
  const lockKey = `seat_lock:${seatId}`;

  // Atomic SETNX with TTL (Set if Not eXists, Expire in X seconds)
  const acquired = await redis.set(lockKey, lockToken, 'EX', timeoutSeconds, 'NX');

  if (acquired !== 'OK') {
    return { success: false, message: 'Seat is currently being held by another customer.' };
  }

  return { success: true, lockToken, lockKey };
}

export async function releaseSeatLock(lockKey: string, lockToken: string) {
  // Execute Lua script atomically on Redis server
  const result = await redis.eval(RELEASE_LOCK_LUA, 1, lockKey, lockToken);
  return result === 1;
}

